import React, { useId } from "react";
import { AbsoluteFill, useCurrentFrame } from "remotion";
import type { PrimitiveProps } from "../primitives";

// Flat IAD blue with a slow, barely-there light drift, film grain and a soft vignette.
const AzulIadLiso: React.FC<PrimitiveProps> = ({ fps }) => {
  const frame = useCurrentFrame();
  const id = useId().replace(/:/g, "");
  const t = frame / fps;
  const gx = 50 + Math.sin(t * 0.12) * 12;
  const gy = 42 + Math.cos(t * 0.09) * 8;

  return (
    <AbsoluteFill style={{ backgroundColor: "#05B8E6" }}>
      <AbsoluteFill style={{ background: `radial-gradient(ellipse at ${gx}% ${gy}%, rgba(255,255,255,0.12) 0%, rgba(255,255,255,0) 55%)` }} />
      <AbsoluteFill style={{ background: "radial-gradient(ellipse at 50% 45%, rgba(0,0,0,0) 55%, rgba(0,0,0,0.2) 100%)" }} />
      <svg width="100%" height="100%" style={{ position: "absolute", inset: 0, opacity: 0.1, mixBlendMode: "overlay" }}>
        <filter id={id}>
          <feTurbulence type="fractalNoise" baseFrequency="0.85" numOctaves={2} seed={frame % 12} />
          <feColorMatrix type="saturate" values="0" />
        </filter>
        <rect width="100%" height="100%" filter={`url(#${id})`} />
      </svg>
    </AbsoluteFill>
  );
};

export default AzulIadLiso;
